"""Screenshot-derived 6-max preflop policy covering 75 documented decision nodes.

The source weights are approximate hand-class frequencies extracted from the
user-provided GTO Wizard screenshots. They are not solver-exact combo weights.
"""
from __future__ import annotations

import base64
import gzip
import json
import math
import itertools
import random
from decimal import Decimal, ROUND_HALF_UP
from dataclasses import dataclass
from functools import lru_cache
from typing import Any

_FULL_POLICY_B64 = ""

POSITIONS_BY_CLOCKWISE_DISTANCE = {0: "BTN", 1: "SB", 2: "BB", 3: "UTG", 4: "HJ", 5: "CO"}
RANKS = "23456789TJQKA"
SUITS = {"s": "s", "♠": "s", "h": "h", "♥": "h",
         "d": "d", "♦": "d", "c": "c", "♣": "c"}


@dataclass(frozen=True)
class ScreenshotRangeDecision:
    action: str
    amount: int | None
    equity_estimate: float = 0.0
    source: str = "screenshot-range"
    node_id: str = ""
    hand_class: str = ""
    action_frequency: float = 0.0
    policy_penalty: int = 0
    guardrail_reason: str = ""


@lru_cache(maxsize=1)
def _data() -> dict[str, Any]:
    raw = gzip.decompress(base64.b64decode(_FULL_POLICY_B64, validate=True))
    parsed = json.loads(raw.decode("utf-8"))
    nodes = parsed.get("nodes")
    if parsed.get("schema") != 1 or parsed.get("node_count") != 75:
        raise RuntimeError("The 75-node preflop screenshot policy is incomplete")
    if not isinstance(nodes, list) or len(nodes) != 75:
        raise RuntimeError("Expected exactly 75 preflop decision nodes")
    indexed = {}
    for node in nodes:
        node_id = str(node.get("id", ""))
        hands = node.get("hands")
        if not node_id or node_id in indexed or not isinstance(hands, dict) or len(hands) != 169:
            raise RuntimeError("Malformed or duplicate preflop node: " + node_id)
        if node.get("actor_position") not in POSITIONS_BY_CLOCKWISE_DISTANCE.values():
            raise RuntimeError("Invalid actor position for " + node_id)
        for combo, actions in hands.items():
            if not isinstance(actions, list):
                raise RuntimeError("Invalid action list: " + node_id + "/" + combo)
            for item in actions:
                frequency = float(item.get("frequency", 0.0))
                if not math.isfinite(frequency) or frequency < 0.0 or frequency > 1.000001:
                    raise RuntimeError("Invalid action weight: " + node_id + "/" + combo)
                action = item.get("action")
                if action not in {"raise", "call", "fold", "allin"}:
                    raise RuntimeError("Unknown action: " + str(action))
                if action == "raise" and item.get("amount_bb") is None:
                    raise RuntimeError("Raise without target size: " + node_id)
        indexed[node_id] = node
    parsed["nodes_by_id"] = indexed
    return parsed


def hand_class_from_cards(cards: Any) -> str | None:
    if isinstance(cards, str):
        raw = cards.strip().replace(" ", "").replace("10", "T")
        if len(raw) != 4:
            return None
        cards = (raw[:2], raw[2:])
    try:
        cards = list(cards)
    except TypeError:
        return None
    if len(cards) != 2:
        return None

    parsed = []
    for card in cards:
        if hasattr(card, "rank") and hasattr(card, "suit"):
            rank, suit_raw = str(card.rank).upper(), str(card.suit)
        else:
            value = str(card).strip().replace("10", "T")
            if len(value) < 2:
                return None
            rank, suit_raw = value[0].upper(), value[-1]
        suit = SUITS.get(suit_raw)
        if rank not in RANKS or suit is None:
            return None
        parsed.append((rank, suit))

    (rank1, suit1), (rank2, suit2) = parsed
    if rank1 == rank2:
        return rank1 + rank2
    high, low = (rank1, rank2) if RANKS.index(rank1) > RANKS.index(rank2) else (rank2, rank1)
    return high + low + ("s" if suit1 == suit2 else "o")


def _parse_card_value(card: Any) -> tuple[str, str] | None:
    """Parse one physical card into (rank, suit), without exposing hidden cards."""
    if hasattr(card, "rank") and hasattr(card, "suit"):
        rank, suit_raw = str(card.rank).upper(), str(card.suit)
    else:
        value = str(card).strip().replace("10", "T")
        if len(value) < 2:
            return None
        rank, suit_raw = value[0].upper(), value[-1]
    suit = SUITS.get(suit_raw)
    if rank not in RANKS or suit is None:
        return None
    return rank, suit


def _available_combos_for_class(combo: str, blockers: set[tuple[str, str]]) -> int:
    """Count physical combinations in one 169-class bucket after known blockers."""
    suits = ("s", "h", "d", "c")
    if len(combo) == 2 and combo[0] == combo[1] and combo[0] in RANKS:
        physical = list(itertools.combinations([(combo[0], suit) for suit in suits], 2))
    elif (len(combo) == 3 and combo[0] in RANKS and combo[1] in RANKS
          and combo[0] != combo[1] and combo[2] in {"s", "o"}
          and RANKS.index(combo[0]) > RANKS.index(combo[1])):
        high, low, kind = combo
        if kind == "s":
            physical = [((high, suit), (low, suit)) for suit in suits]
        else:
            physical = [((high, first), (low, second))
                        for first in suits for second in suits if first != second]
    else:
        return 0
    return sum(1 for cards in physical if not any(card in blockers for card in cards))


def _player_id(player: Any) -> str:
    value = getattr(player, "player_id", None)
    return str(value) if value is not None else ""


def _seat_position_map(table: Any, hand: Any) -> dict[str, str] | None:
    players = list(getattr(hand, "players", ()) or ())
    if len(players) != 6:
        return None
    dealer = getattr(table, "dealer_index", None)
    if dealer is None:
        dealer = getattr(hand, "dealer_index", None)
    if dealer is None:
        return None
    try:
        dealer = int(dealer) % 6
    except (TypeError, ValueError):
        return None

    seat_by_id = getattr(hand, "seat_by_id", {}) or {}
    result: dict[str, str] = {}
    for index, player in enumerate(players):
        pid = _player_id(player)
        if not pid:
            return None
        seat = None
        if isinstance(seat_by_id, dict) and pid in seat_by_id:
            try:
                seat = int(seat_by_id[pid]) % 6
            except (TypeError, ValueError):
                return None
        else:
            seat = index
        result[pid] = POSITIONS_BY_CLOCKWISE_DISTANCE[(seat - dealer) % 6]
    return result


def _supports_100bb_effective_stack(hand: Any) -> bool:
    """The supplied chart set is 6-max cash at 100 BB; never reuse it at other depths."""
    try:
        big_blind = float(getattr(hand, "big_blind", 0) or 0)
        players = list(getattr(hand, "players", ()) or ())
    except (TypeError, ValueError):
        return False
    if big_blind <= 0 or len(players) != 6:
        return False

    # Every dealt-in seat can influence the preflop line, including players
    # who later fold. A short-stacked player must not disappear from this check.
    participants = [player for player in players if _player_id(player)]
    if len(participants) != 6:
        return False
    # A six-seat table object is not necessarily a six-handed deal: players
    # sitting out can still occupy player objects. The screenshots are for
    # six dealt-in positions, so require two hole cards at every seat. Folded
    # players retain their dealt cards and remain part of the preflop history.
    for player in participants:
        try:
            if len(list(getattr(player, "hole_cards", ()) or ())) != 2:
                return False
        except TypeError:
            return False
    for player in participants:
        stack = getattr(player, "stack", None)
        contribution = getattr(player, "total_contribution", None)
        if contribution is None:
            contribution = getattr(player, "street_contribution", None)
        try:
            starting_stack_bb = (float(stack) + float(contribution)) / big_blind
        except (TypeError, ValueError):
            return False
        if not math.isfinite(starting_stack_bb) or abs(starting_stack_bb - 100.0) > 0.25:
            return False
    return True


def _event_player_id(event: dict[str, Any], hand: Any) -> str | None:
    direct = event.get("player_id") or event.get("player")
    direct_text = str(direct) if direct is not None else ""
    players = list(getattr(hand, "players", ()) or ())
    for player in players:
        pid = _player_id(player)
        name = str(getattr(player, "name", ""))
        if direct_text and direct_text in {pid, name}:
            return pid
    return None


def _normalise_action(event: dict[str, Any]) -> str:
    raw = str(event.get("action", "")).strip().lower().replace("-", "_").replace(" ", "_")
    if event.get("is_all_in") or event.get("all_in") or event.get("jam"):
        return "allin"
    if raw in {"allin", "all_in", "jam", "shove"}:
        return "allin"
    if raw in {"raise", "bet", "raise_to", "bet_to"}:
        return "raise"
    if raw in {"fold", "folded"}:
        return "fold"
    if raw in {"call", "called"}:
        return "call"
    return raw


def _event_target_bb(event: dict[str, Any], hand: Any, player_id: str) -> float | None:
    try:
        big_blind = float(getattr(hand, "big_blind", 0) or 0)
    except (TypeError, ValueError):
        return None
    if big_blind <= 0:
        return None

    target = None
    for key in ("target", "raise_to", "amount_to"):
        if event.get(key) is not None:
            target = event.get(key)
            break
    if target is None:
        try:
            target = getattr(hand.player(player_id), "street_contribution", None)
        except Exception:
            target = None
    try:
        amount_bb = float(target) / big_blind
    except (TypeError, ValueError):
        return None
    return amount_bb if math.isfinite(amount_bb) and amount_bb >= 0 else None


def _non_fold_history(hand: Any) -> list[tuple[str, dict[str, Any], str]] | None:
    result = []
    for event in list(getattr(hand, "events", ()) or ()):
        if not isinstance(event, dict) or event.get("type") != "action":
            continue
        street = str(event.get("street", "preflop")).lower().replace("-", "")
        if street != "preflop":
            continue
        action = _normalise_action(event)
        if action == "fold":
            continue
        player_id = _event_player_id(event, hand)
        if player_id is None:
            return None
        result.append((player_id, event, action))
    return result


def _node_for_actor(table: Any, hand: Any, actor_id: str) -> str | None:
    if not _supports_100bb_effective_stack(hand):
        return None
    positions = _seat_position_map(table, hand)
    if positions is None or actor_id not in positions:
        return None
    actual_history = _non_fold_history(hand)
    if actual_history is None:
        return None

    nodes = _data()["nodes"]
    actor_position = positions[actor_id]
    for node in nodes:
        if node["actor_position"] != actor_position:
            continue
        expected = node["history"]
        if len(expected) != len(actual_history):
            continue
        matched = True
        for expected_item, (pid, event, actual_action) in zip(expected, actual_history):
            if positions.get(pid) != expected_item["pos"] or actual_action != expected_item["action"]:
                matched = False
                break
            expected_amount = expected_item.get("amount_bb")
            if expected_amount is not None:
                actual_amount = _event_target_bb(event, hand, pid)
                if actual_amount is None:
                    matched = False
                    break
                if not _history_size_matches(
                    actual_amount, expected_amount, int(hand.big_blind), expected_item["action"]
                ):
                    matched = False
                    break
        if matched:
            return node["id"]
    return None


def _node_for_historical_action(table: Any, hand: Any, positions: dict[str, str],
                                prior_events: list[dict[str, Any]], actor_id: str) -> dict[str, Any] | None:
    """Find the chart decision that immediately preceded one recorded action."""
    prefix: list[tuple[str, dict[str, Any], str]] = []
    for event in prior_events:
        if not isinstance(event, dict) or event.get("type") != "action":
            continue
        street = str(event.get("street", "preflop")).lower().replace("-", "")
        if street != "preflop":
            continue
        action = _normalise_action(event)
        if action == "fold":
            continue
        pid = _event_player_id(event, hand)
        if pid is None:
            return None
        prefix.append((pid, event, action))

    actor_position = positions.get(actor_id)
    if actor_position is None:
        return None
    for node in _data()["nodes"]:
        if node["actor_position"] != actor_position or len(node["history"]) != len(prefix):
            continue
        matched = True
        for expected, (pid, event, action) in zip(node["history"], prefix):
            if positions.get(pid) != expected["pos"] or action != expected["action"]:
                matched = False
                break
            expected_amount = expected.get("amount_bb")
            if expected_amount is not None:
                actual_amount = _event_target_bb(event, hand, pid)
                if actual_amount is None or not _history_size_matches(
                    actual_amount, expected_amount, int(hand.big_blind), expected["action"]
                ):
                    matched = False
                    break
        if matched:
            return node
    return None


def _action_mass_for_observation(node: dict[str, Any], action: str,
                                 event: dict[str, Any], hand: Any,
                                 actor_id: str,
                                 blockers: set[tuple[str, str]] | None = None) -> tuple[dict[str, float], float]:
    """Return class action weights multiplied by remaining physical combo counts."""
    observed_target = _event_target_bb(event, hand, actor_id) if action in {"raise", "allin"} else None
    if action in {"raise", "allin"} and observed_target is None:
        return {}, 0.0
    blockers = blockers or set()
    per_class: dict[str, float] = {}
    total_mass = 0.0
    for combo, raw_actions in node["hands"].items():
        weight = 0.0
        for item in raw_actions:
            if item.get("action") != action:
                continue
            if action in {"raise", "allin"}:
                target = item.get("amount_bb")
                if target is None:
                    continue
                if not _history_size_matches(
                    observed_target, target, int(getattr(hand, "big_blind", 0) or 0), action
                ):
                    continue
            weight += max(0.0, float(item.get("frequency", 0.0)))
        if weight > 0.0:
            multiplicity = _available_combos_for_class(combo, blockers)
            if multiplicity <= 0:
                continue
            mass = weight * multiplicity
            per_class[combo] = mass
            total_mass += mass
    return per_class, total_mass


def _known_public_blockers(hand: Any, exclude_player_id: str | None) -> tuple[set[tuple[str, str]], list[str]] | None:
    """Use only the acting hero's cards and public board cards; never other players' hidden cards."""
    blockers: set[tuple[str, str]] = set()
    labels: list[str] = []
    if exclude_player_id is not None:
        target = str(exclude_player_id)
        player = next((p for p in list(getattr(hand, "players", ()) or ())
                       if _player_id(p) == target), None)
        if player is None:
            return None
        cards = list(getattr(player, "hole_cards", ()) or ())
        if len(cards) != 2:
            return None
        for card in cards:
            parsed = _parse_card_value(card)
            if parsed is None or parsed in blockers:
                return None
            blockers.add(parsed)
            labels.append(parsed[0] + parsed[1])
    for card in list(getattr(hand, "board", ()) or ()):
        parsed = _parse_card_value(card)
        if parsed is None or parsed in blockers:
            return None
        blockers.add(parsed)
        labels.append(parsed[0] + parsed[1])
    return blockers, sorted(labels)


def estimate_preflop_opponent_ranges(table: Any, hand: Any,
                                     exclude_player_id: str | None = None,
                                     opponent_profiles: dict[str, Any] | None = None,
                                     opponent_learning: dict[str, dict[str, float]] | None = None) -> dict[str, Any]:
    """Estimate latest supported opponent ranges, adjusted for known hero/board blockers.

    Screenshot-derived per-class weights are multiplied by the number of physical
    combinations still available in each class. Only the supplied acting player's
    cards and the public board are used as blockers; the other seats' hidden cards
    are deliberately ignored. Suit-specific strategy differences remain unknown.
    Known CPU profile archetypes are attached as weak behavioral priors; they do not
    alter the fixed chart rows or frequencies.
    """
    if not _supports_100bb_effective_stack(hand):
        return {"supported": False, "reason": "requires_six_player_100bb_table", "players": {}}
    positions = _seat_position_map(table, hand)
    if positions is None:
        return {"supported": False, "reason": "seat_positions_unavailable", "players": {}}
    blocker_result = _known_public_blockers(hand, exclude_player_id)
    public_blocker_result = _known_public_blockers(hand, None)
    if blocker_result is None or public_blocker_result is None:
        return {"supported": False, "reason": "known_blocker_cards_unavailable_or_invalid", "players": {}}
    blockers, blocker_labels = blocker_result
    public_blockers, _public_blocker_labels = public_blocker_result
    remaining_cards = 52 - len(blockers)
    available_combos = remaining_cards * (remaining_cards - 1) // 2
    if available_combos <= 0:
        return {"supported": False, "reason": "no_available_combinations_after_blockers", "players": {}}

    latest: dict[str, dict[str, Any]] = {}
    prior_events: list[dict[str, Any]] = []
    for event in list(getattr(hand, "events", ()) or ()):
        if not isinstance(event, dict) or event.get("type") != "action":
            continue
        street = str(event.get("street", "preflop")).lower().replace("-", "")
        if street != "preflop":
            continue
        actor_id = _event_player_id(event, hand)
        if actor_id is None or actor_id not in positions:
            continue
        action = _normalise_action(event)
        if action not in {"raise", "allin", "call", "fold"}:
            latest[actor_id] = {
                "supported": False,
                "position": positions[actor_id],
                "action": action,
                "reason": "unsupported_action_type",
            }
            prior_events.append(event)
            continue

        node = _node_for_historical_action(table, hand, positions, prior_events, actor_id)
        if node is None:
            latest[actor_id] = {
                "supported": False,
                "position": positions[actor_id],
                "action": action,
                "reason": "unsupported_preflop_history",
            }
        else:
            masses, total_mass = _action_mass_for_observation(
                node, action, event, hand, actor_id, blockers=blockers)
            unblocked_masses, unblocked_total_mass = _action_mass_for_observation(
                node, action, event, hand, actor_id, blockers=public_blockers)
            if total_mass <= 0.0:
                latest[actor_id] = {
                    "supported": False,
                    "position": positions[actor_id],
                    "action": action,
                    "node_id": node["id"],
                    "reason": "action_has_no_positive_range_mass_after_blockers",
                }
            else:
                probabilities = {combo: mass / total_mass for combo, mass in masses.items()}
                unblocked_probabilities = (
                    {combo: mass / unblocked_total_mass
                     for combo, mass in unblocked_masses.items()}
                    if unblocked_total_mass > 0.0 else probabilities
                )
                latest[actor_id] = {
                    "supported": True,
                    "position": positions[actor_id],
                    "action": action,
                    "node_id": node["id"],
                    "source_image": node.get("source_image", ""),
                    "combo_mass": total_mass,
                    "combo_mass_without_hero_blockers": unblocked_total_mass,
                    "available_combos": available_combos,
                    "range_percent_of_available_combos": total_mass / available_combos * 100.0,
                    "hand_class_probabilities": probabilities,
                    "unblocked_hand_class_probabilities": unblocked_probabilities,
                    "method": "screenshot-derived action weights with exact public-card and hero-card removal; unblocked weights retained for blocker diagnostics",
                }
        prior_events.append(event)

    if exclude_player_id is not None:
        latest.pop(str(exclude_player_id), None)

    # The 100-player CPU pool carries stable archetype labels. They are weak
    # starting priors; observed, per-identity behavior gradually takes priority.
    profile_map = opponent_profiles or {}
    learning_map = opponent_learning or {}
    allowed_archetypes = {"aggressive", "calling_station", "overfolder", "underbluffer"}
    profile_ids = {
        str(player_id) for player_id in
        (set(latest) | set(profile_map) | set(learning_map))
        if str(player_id) != str(exclude_player_id)
    }
    for player_id in sorted(profile_ids):
        # A CPU may have folded before showing a chart-supported action, or not
        # acted yet. Still attach its persistent profile so later postflop
        # reasoning can use the identity's history without inventing a chart row.
        row = latest.setdefault(player_id, {
            "supported": False,
            "position": positions.get(player_id, ""),
            "action": "unobserved",
            "reason": "behavior-profile-prior",
        })
        profile = profile_map.get(str(player_id))
        if isinstance(profile, dict):
            archetype = profile.get("archetype", "balanced")
            profile_level = profile.get("level")
        elif profile is not None:
            archetype = getattr(profile, "archetype", "balanced")
            profile_level = getattr(profile, "level", None)
        else:
            archetype, profile_level = "balanced", None
        archetype = str(archetype or "balanced").lower()
        if archetype in allowed_archetypes:
            row["archetype"] = archetype
        if profile_level is not None:
            try:
                row["profile_level"] = max(1, min(5, int(profile_level)))
            except (TypeError, ValueError, OverflowError):
                pass

        learned = learning_map.get(str(player_id))
        if isinstance(learned, dict):
            clean = {}
            for key, value in learned.items():
                try:
                    number = float(value)
                    if math.isfinite(number):
                        clean[str(key)] = number
                except (TypeError, ValueError, OverflowError):
                    continue
            if clean:
                row["learned_behavior"] = clean
                hands = clean.get("sample_hands", 0.0)
                fold_opp = clean.get("faced_bet_opportunities", 0.0)
                call_opp = clean.get("postflop_actions", 0.0)
                vpip = clean.get("vpip_rate", 0.22)
                pfr = clean.get("pfr_rate", 0.16)
                fold_rate = clean.get("fold_to_bet_rate", 0.55)
                call_rate = clean.get("postflop_call_rate", 0.30)
                aggression = clean.get("postflop_aggression_rate", 0.22)
                three_bet_opp = clean.get("three_bet_opportunities", 0.0)
                three_bet_rate = clean.get("three_bet_rate", 0.07)
                four_bet_opp = clean.get("four_bet_opportunities", 0.0)
                four_bet_rate = clean.get("four_bet_rate", 0.04)
                learned_archetype = None
                learned_basis = ""
                # Require enough real hands/opportunities before classifying a CPU.
                if hands >= 12 and fold_opp >= 12 and fold_rate >= 0.72:
                    learned_archetype = "overfolder"
                    learned_basis = "fold_to_bet"
                elif (hands >= 20 and vpip >= 0.30 and vpip - pfr >= 0.17
                      and call_opp >= 16 and call_rate >= 0.38):
                    learned_archetype = "calling_station"
                    learned_basis = "vpip_gap_and_postflop_calls"
                elif (hands >= 24 and (
                      (call_opp >= 24 and aggression >= 0.31 and pfr >= 0.18)
                      or (three_bet_opp >= 16 and three_bet_rate >= 0.18 and pfr >= 0.18)
                      or (four_bet_opp >= 10 and four_bet_rate >= 0.18 and pfr >= 0.18)
                )):
                    learned_archetype = "aggressive"
                    learned_basis = (
                        "three_bet_rate" if three_bet_opp >= 16 and three_bet_rate >= 0.18
                        else ("four_bet_rate" if four_bet_opp >= 10 and four_bet_rate >= 0.18
                              else "postflop_aggression")
                    )
                if learned_archetype is not None:
                    row["archetype"] = learned_archetype
                    row["learned_archetype"] = learned_archetype
                    row["learned_archetype_basis"] = learned_basis
                row["learned_behavior_confidence"] = min(0.85, hands / (hands + 30.0)) if hands > 0 else 0.0

    return {
        "supported": True,
        "reason": "",
        "table_depth_bb": 100,
        "blocker_cards": blocker_labels,
        "available_combos": available_combos,
        "players": latest,
    }


def _legal_actions(hand: Any, actor_id: str) -> dict[str, Any]:
    try:
        value = hand.legal_actions(actor_id)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _bb_target_to_cents(amount_bb: Any, big_blind_cents: int) -> int:
    """Convert a fixed chart BB target to the nearest available cent.

    ROUND_HALF_UP avoids Python's ties-to-even behavior: 2.5 * 25
    must not silently become 62 cents (2.48 BB) at NL25. The chart
    source remains 2.50 BB; only currency denomination is rounded.
    """
    blind = int(big_blind_cents)
    amount = Decimal(str(amount_bb)) * Decimal(blind)
    if not amount.is_finite() or amount < 0 or blind <= 0:
        raise ValueError("Invalid fixed chart BB target")
    return int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _history_size_matches(actual_amount_bb: float, expected_amount_bb: float,
                          big_blind_cents: int, action: str) -> bool:
    """Match observed history to the immutable chart with a 5% size tolerance.

    This tolerance is only for recognizing an opponent's historical action.
    It never changes the chart's stored frequencies or the CPU's fixed BB target.
    All-in matching retains its existing wider 0.75 BB tolerance.
    """
    try:
        blind = int(big_blind_cents)
        actual_bb = Decimal(str(actual_amount_bb))
        expected_bb = Decimal(str(expected_amount_bb))
        if blind <= 0 or not actual_bb.is_finite() or not expected_bb.is_finite():
            return False
        if action == "allin":
            return abs(actual_bb - expected_bb) <= Decimal("0.75")
        expected_cents = Decimal(_bb_target_to_cents(expected_bb, blind))
        actual_cents = actual_bb * Decimal(blind)
        tolerance_cents = max(Decimal("0.5"), abs(expected_cents) * Decimal("0.05"))
        return abs(actual_cents - expected_cents) <= tolerance_cents
    except (TypeError, ValueError, ArithmeticError, OverflowError):
        return False


def _guardrail_preflop_decision(hand: Any, actor_id: str, cpu: Any,
                                reason: str) -> ScreenshotRangeDecision | None:
    """Never stop or use a legacy untrained action when chart history is unmatched."""
    legal = _legal_actions(hand, str(actor_id))
    legal_names = {
        str(value).lower().replace("-", "_"): str(value).lower()
        for value in legal.get("actions", ())
    }
    # A free check is preferred; facing a wager, fold is safer than inventing
    # a call/raise line. Call is only a last resort when it is the sole passive
    # legal action. No off-chart bet, raise or shove is ever generated here.
    if "check" in legal_names:
        action = legal_names["check"]
    elif "fold" in legal_names:
        action = legal_names["fold"]
    elif "call" in legal_names:
        action = legal_names["call"]
    else:
        return None

    try:
        previous = max(0, int(getattr(cpu, "_preflop_policy_penalty", 0) or 0))
    except (TypeError, ValueError, OverflowError):
        previous = 0
    penalty = min(100000, previous + 100)
    try:
        setattr(cpu, "_preflop_policy_penalty", penalty)
    except Exception:
        pass
    try:
        hand_class = hand_class_from_cards(getattr(hand.player(actor_id), "hole_cards", ())) or ""
    except Exception:
        hand_class = ""
    return ScreenshotRangeDecision(
        action=action, amount=None, source="preflop-guardrail",
        node_id="", hand_class=hand_class, action_frequency=0.0,
        policy_penalty=penalty, guardrail_reason=str(reason)[:160],
    )


def _clamp_raise_target(desired: int, legal: dict[str, Any]) -> int | None:
    """Accept the fixed chart target unchanged; never resize it to fit."""
    try:
        target = int(desired)
        minimum = legal.get("min_target")
        maximum = legal.get("max_target")
        if target <= 0:
            return None
        if minimum is not None and target < int(minimum):
            return None
        if maximum is not None and target > int(maximum):
            return None
        return target
    except (TypeError, ValueError, OverflowError):
        return None

def _decision_choices(node: dict[str, Any], combo: str, hand: Any,
                      actor_id: str, legal: dict[str, Any]) -> list[tuple[str, int | None, float]]:
    raw_actions = node["hands"].get(combo)
    if not raw_actions:
        return []
    legal_action_names = {
        str(value).lower().replace("-", "_"): str(value).lower()
        for value in legal.get("actions", ())
    }
    legal_names = set(legal_action_names)
    choices: list[tuple[str, int | None, float]] = []
    try:
        big_blind = int(getattr(hand, "big_blind", 0) or 0)
    except (TypeError, ValueError):
        big_blind = 0

    for item in raw_actions:
        weight = max(0.0, float(item.get("frequency", 0.0)))
        if weight <= 0:
            continue
        action = item["action"]
        if action == "raise":
            target_key = "raise" if "raise" in legal_names else ("bet" if "bet" in legal_names else None)
            if target_key is None or big_blind <= 0:
                continue
            target_action = legal_action_names[target_key]
            desired = _bb_target_to_cents(item["amount_bb"], big_blind)
            target = _clamp_raise_target(desired, legal)
            if target is not None:
                choices.append((target_action, target, weight))
        elif action == "call":
            if "call" in legal_names:
                choices.append((legal_action_names["call"], None, weight))
            elif "check" in legal_names:
                choices.append((legal_action_names["check"], None, weight))
        elif action == "fold":
            if "fold" in legal_names:
                choices.append((legal_action_names["fold"], None, weight))
        elif action == "allin":
            allin_key = next((candidate for candidate in ("allin", "all_in", "jam", "shove")
                              if candidate in legal_names), None)
            if allin_key is not None:
                choices.append((legal_action_names[allin_key], None, weight))
            elif ("raise" in legal_names or "bet" in legal_names) and legal.get("max_target") is not None:
                max_target = _clamp_raise_target(int(legal["max_target"]), legal)
                if max_target is not None:
                    target_key = "raise" if "raise" in legal_names else "bet"
                    target_action = legal_action_names[target_key]
                    choices.append((target_action, max_target, weight))
    return choices


def _sample_action(choices: list[tuple[str, int | None, float]], rng: Any):
    total = sum(weight for _, _, weight in choices)
    if total <= 0:
        return None
    threshold = float(rng.random()) * total
    for action, amount, weight in choices:
        threshold -= weight
        if threshold < 0:
            return action, amount, weight
    return choices[-1]


def _choose_preflop_action_from_chart(table: Any, hand: Any, actor_id: str, cpu: Any,
                          fallback_decision: Any = None) -> ScreenshotRangeDecision | Any | None:
    """Choose from the 75 screenshot nodes; unsupported trees use the legacy CPU."""
    if str(getattr(hand, "street", "")).lower() != "preflop":
        return None
    node_id = _node_for_actor(table, hand, str(actor_id))
    if node_id is None:
        return None
    try:
        player = hand.player(actor_id)
        combo = hand_class_from_cards(getattr(player, "hole_cards", ()))
        if combo is None:
            return None
        node = _data()["nodes_by_id"][node_id]
        raw_actions = node["hands"].get(combo)
        rng = getattr(cpu, "rng", None)
        if not hasattr(rng, "random"):
            rng = random.Random()
        legal = _legal_actions(hand, str(actor_id))
        legal_action_names = {
            str(value).lower().replace("-", "_"): str(value).lower()
            for value in legal.get("actions", ())
        }
        # A zero-frequency hand class is outside the chart's action range.
        # Treat that as the chart's 100% FOLD, never as a legacy-CPU request.
        if not raw_actions or not any(float(a.get("frequency", 0.0)) > 0 for a in raw_actions):
            fold_action = legal_action_names.get("fold")
            if fold_action is None:
                return None
            return ScreenshotRangeDecision(
                action=fold_action, amount=None, source="screenshot-range",
                node_id=node_id, hand_class=combo, action_frequency=1.0,
            )
        choices = _decision_choices(node, combo, hand, str(actor_id), legal)
        selected = _sample_action(choices, rng)
        if selected is None:
            return None
        action, amount, frequency = selected
        return ScreenshotRangeDecision(
            action=action, amount=amount, source="screenshot-range",
            node_id=node_id, hand_class=combo, action_frequency=frequency,
        )
    except (AttributeError, KeyError, TypeError, ValueError, RuntimeError, OverflowError):
        return None




def choose_preflop_action(table: Any, hand: Any, actor_id: str, cpu: Any,
                          fallback_decision: Any = None) -> ScreenshotRangeDecision | None:
    """Use the fixed screenshot chart; on a miss, keep playing under strict guardrails."""
    if str(getattr(hand, "street", "")).lower() != "preflop":
        return None
    try:
        decision = _choose_preflop_action_from_chart(table, hand, actor_id, cpu, None)
        if decision is not None:
            return decision
        return _guardrail_preflop_decision(
            hand, actor_id, cpu, "history_not_covered_by_fixed_75_node_chart"
        )
    except Exception as exc:
        return _guardrail_preflop_decision(
            hand, actor_id, cpu, "chart_lookup_error:" + type(exc).__name__
        )



def preflop_chart_options(table: Any, hand: Any, actor_id: str) -> dict[str, Any] | None:
    """Return only chart-supported Fold, Call/Check and fixed-BB Raise choices."""
    if str(getattr(hand, "street", "")).lower() != "preflop":
        return None
    node_id = _node_for_actor(table, hand, str(actor_id))
    if node_id is None:
        return None
    try:
        player = hand.player(actor_id)
        combo = hand_class_from_cards(getattr(player, "hole_cards", ()))
        if combo is None:
            return None
        node = _data()["nodes_by_id"][node_id]
        raw = node["hands"].get(combo) or []
        legal = _legal_actions(hand, str(actor_id))
        if not any(float(a.get("frequency", 0.0)) > 0 for a in raw):
            return {"node_id": node_id, "hand_class": combo, "fold": True,
                    "call_action": None, "raise_action": None, "raise_amount": None,
                    "raise_frequency": 0.0}
        choices = _decision_choices(node, combo, hand, str(actor_id), legal)
        fold = False
        call_action = None
        raises: dict[tuple[str, int], float] = {}
        max_target = int(legal.get("max_target", 0) or 0)
        for action, amount, weight in choices:
            key = str(action).lower().replace("-", "_")
            if key == "fold":
                fold = True
            elif key in {"call", "check"}:
                if call_action is None or key == "call":
                    call_action = key
            elif key in {"allin", "all_in", "jam", "shove"}:
                if max_target > 0:
                    option = ("all-in", max_target)
                    raises[option] = raises.get(option, 0.0) + float(weight)
            elif key in {"raise", "bet"} and amount is not None:
                option = (key, int(amount))
                raises[option] = raises.get(option, 0.0) + float(weight)
        chosen = max(raises.items(), key=lambda item: (item[1], -item[0][1]), default=None)
        return {
            "node_id": node_id, "hand_class": combo, "fold": bool(fold),
            "call_action": call_action,
            "raise_action": chosen[0][0] if chosen else None,
            "raise_amount": chosen[0][1] if chosen else None,
            "raise_frequency": float(chosen[1]) if chosen else 0.0,
        }
    except (AttributeError, KeyError, TypeError, ValueError, RuntimeError, OverflowError):
        return None



def preflop_situation_size(table: Any, hand: Any, actor_id: str) -> int | None:
    """Return the dominant chart size for a positional/action-history node.

    This intentionally does not inspect the actor's hole-card class. The spot
    key is the actor's seat position plus the complete observed preflop action
    and sizing history, as resolved by _node_for_actor(). When a node mixes
    sizes, choose the population-weighted modal size across all 1,326 physical
    starting combinations, not the size preferred by the current hand.
    """
    if str(getattr(hand, "street", "")).lower() != "preflop":
        return None
    legal = _legal_actions(hand, str(actor_id))
    legal_names = {
        str(value).lower().replace("-", "_")
        for value in legal.get("actions", ())
    }
    if not ({"raise", "bet"} & legal_names):
        return None
    node_id = _node_for_actor(table, hand, str(actor_id))
    if node_id is None:
        return None
    node = _data().get("nodes_by_id", {}).get(node_id)
    if not isinstance(node, dict):
        return None
    try:
        big_blind = int(getattr(hand, "big_blind", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        return None
    if big_blind <= 0:
        return None

    size_mass: dict[int, float] = {}
    maximum = max(0, int(legal.get("max_target", 0) or 0))
    for hand_class, raw_actions in node.get("hands", {}).items():
        physical_count = _available_combos_for_class(str(hand_class), set())
        if physical_count <= 0:
            continue
        for item in raw_actions:
            action = str(item.get("action", "")).lower()
            try:
                frequency = max(0.0, float(item.get("frequency", 0.0) or 0.0))
            except (TypeError, ValueError, OverflowError):
                continue
            # The control selects a normal raise size, not an all-in action.
            # All-in remains a separate strategic choice in the BOT's
            # hand-class-specific chart policy and is never used as a size preset.
            if frequency <= 0.0 or action != "raise":
                continue
            amount_bb = item.get("amount_bb")
            if amount_bb is None:
                continue
            try:
                target_cents = _bb_target_to_cents(amount_bb, big_blind)
            except (TypeError, ValueError, ArithmeticError, OverflowError):
                continue
            if target_cents <= 0 or target_cents > maximum:
                continue
            size_mass[target_cents] = (
                size_mass.get(target_cents, 0.0) + frequency * physical_count
            )
    if not size_mass:
        return None
    # A modal spot-level size gives one stable suggestion without consulting
    # the player's cards. In a tie, prefer the smaller size to avoid silently
    # escalating the user's amount.
    return max(size_mass.items(), key=lambda item: (item[1], -item[0]))[0]


def coverage_summary() -> dict[str, Any]:
    data = _data()
    return {
        "node_count": len(data["nodes"]),
        "hand_classes_per_node": data["hand_classes_per_node"],
        "hand_rows": sum(len(node["hands"]) for node in data["nodes"]),
        "source": data["source"],
        "method": data["method"],
    }